package org.apache.accumulo.test.ample;

import static org.apache.accumulo.core.util.LazySingletons.RANDOM;

import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;

import org.apache.accumulo.core.client.ConditionalWriter;
import org.apache.accumulo.core.client.ConditionalWriter.Result;
import org.apache.accumulo.core.client.ConditionalWriter.Status;
import org.apache.accumulo.core.data.ConditionalMutation;
import org.apache.accumulo.test.ample.metadata.ConditionalWriterInterceptor;
import org.apache.hadoop.io.Text;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * A {@link ConditionalWriterInterceptor} that simulates ambiguous conditional mutation outcomes.
 * For each mutation one of three outcomes is randomly chosen:
 *
 * <ol>
 * <li>The mutation is not written and an {@link Status#UNKNOWN} result is returned.</li>
 * <li>The mutation is written but an {@link Status#UNKNOWN} result is returned.</li>
 * <li>The mutation is written and its actual result is returned.</li>
 * </ol>
 *
 * This exercises code paths that must be able to handle the ambiguous {@link Status#UNKNOWN} status
 * that can occur when the outcome of a conditional write is not known.
 */
public class FlakyInterceptor implements ConditionalWriterInterceptor {

  private static final Logger log = LoggerFactory.getLogger(FlakyInterceptor.class);

  @Override
  public Iterator<Result> write(ConditionalWriter writer,
      Iterator<ConditionalMutation> mutations) {
    List<Result> results = new ArrayList<>();
    List<ConditionalMutation> toWrite = new ArrayList<>();

    while (mutations.hasNext()) {
      ConditionalMutation mutation = mutations.next();
      if (RANDOM.get().nextDouble() <= 0.33) {
        // Outcome 1: do not write the mutation and return an unknown status
        results.add(new Result(Status.UNKNOWN, mutation, "flaky"));
        log.debug("Returning unknown for unwritten mutation with row: {}",
            new Text(mutation.getRow()));
      } else {
        toWrite.add(mutation);
      }
    }

    if (!toWrite.isEmpty()) {
      Iterator<Result> writeResults = writer.write(toWrite.iterator());
      while (writeResults.hasNext()) {
        Result result = writeResults.next();
        if (RANDOM.get().nextBoolean()) {
          // Outcome 2: write the mutation but return an unknown status
          results.add(new Result(Status.UNKNOWN, result.getMutation(), result.getTabletServer()));
          log.debug("Returning unknown for written mutation with row: {}",
              new Text(result.getMutation().getRow()));
        } else {
          // Outcome 3: write the mutation and return the actual status
          results.add(result);
        }
      }
    }

    return results.iterator();
  }

  @Override
  public Result write(ConditionalWriter writer, ConditionalMutation mutation) {
    return write(writer, List.of(mutation).iterator()).next();
  }
}
